#!/bin/bash
# Runs each step for real and records "$ command" + its actual output (same method as the 6.4 article).
TD=/workspace/rea-65/transcripts
PRE='source ~/.local/rea65-env.sh; cd /workspace/re/lab65;'
step() { local name=$1; shift; : > $TD/$name.txt; for c in "$@"; do echo "\$ $c" >> $TD/$name.txt; timeout 600 bash -c "$PRE $c" >> $TD/$name.txt 2>&1; echo >> $TD/$name.txt; done; echo "done $name"; }
ONLY="$*"; want() { [ -z "$ONLY" ] || [[ " $ONLY " == *" $1 "* ]]; }
want t01 && step t01-tco "curl -sI https://t.co/8VhocJiXYK | grep -i -E '^(HTTP|location)'" "curl -s https://api.github.com/repos/morluto/rea/releases/tags/rea-agents-6.5.0 | jq '{name, tag_name, published_at, url: .html_url}'" "TZ=America/New_York date -d 2026-10-14T12:32:45Z"
want t02 && step t02-update "npm install -g rea-agents@latest 2>&1 | grep -v -E 'EBADENGINE|package:|required:|current:|^npm WARN EBADENGINE }|^}' | tail -3" "rea --version" "npm view rea-agents dist-tags --json" "cd /workspace/rea-src && git pull --ff-only 2>&1 | tail -1 && git log --oneline -1 && git describe --tags --match 'rea-agents-*'"
want t03 && step t03-doctor-ghidra "rea doctor --provider ghidra --json | jq -r '\"healthy: \\(.healthy)\", (.scope_checks[] | \"  \\(.classification)  \\(.name)  \\(.detail)\")'"
want t04 && step t04-gaps "rea --help | grep -E 'inspect-(go-binary|sqlite-database|pcap-capture|packet-capture|wasm-artifact|rust-binary|electron-fuses)|compare-wasm-interfaces'" "grep -m1 'version:' ~/.local/lib/node_modules/rea-agents/skills/reverse-engineer-anything/SKILL.md; grep -m1 'version:' /workspace/rea-src/.agents/skills/reverse-engineer-anything/SKILL.md"
want t06 && step t06-js-selected "find js/dist -type f | sort" "rea analyze-javascript-application \$PWD/js/dist --source-path index.js --source-path chunks/checkout-C55LDPC2.js --format json 2>/dev/null | tail -1 > notes/js-selected.ev.json" "jq -c '.normalized_result | .source_selection, .statistics' notes/js-selected.ev.json" "jq -r -f /workspace/rea-65/tools/jsedges.jq notes/js-selected.ev.json"
want t07 && step t07-js-full "rea analyze-javascript-application \$PWD/js/dist --format json 2>/dev/null | tail -1 > notes/js-full.ev.json" "jq -c '.normalized_result | {source_selection, parsed: .statistics.parsed_javascript_files, coverage: .graph.coverage.status}' notes/js-selected.ev.json notes/js-full.ev.json"
want t08 && rm -rf /workspace/re/lab65/notes/rec-one /workspace/re/lab65/notes/rec-all
want t08 && step t08-recover "ls js/wp-dist" "rea recover-javascript-sources \$PWD/js/wp-dist/src_checkout_js.chunk.js \$PWD/notes/rec-one --format json | tail -1 | jq -c '.raw_result.report | {detected_formats, modules: [.modules[].filename]}'" "sed -n 1,3p notes/rec-one/modules/src/checkout.js" "rea recover-javascript-sources \$PWD/js/wp-dist/main.js \$PWD/notes/rec-all --additional-path \$PWD/js/wp-dist/runtime.js --additional-path \$PWD/js/wp-dist/shared.js --additional-path \$PWD/js/wp-dist/src_checkout_js.chunk.js --additional-path \$PWD/js/wp-dist/src_settings_js.chunk.js --format json | tail -1 | jq -c '{status: .normalized_result.status, runtime_equivalence: .normalized_result.runtime_equivalence, report: (.raw_result.report | {detected_formats, modules: [.modules[].filename]})}'" "sed -n 1,3p notes/rec-all/modules/src/checkout.js"
want t10 && step t10-cli-view "jq -c '{source: {kind: \"inline\", evidence: .}, view: {kind: \"wasm\", facet: \"imports\", offset: 0, limit: 5}}' notes/wasm-v1.json > notes/wasm-view.json" "rea inspect-analysis-view notes/wasm-view.json --format json | jq -c '.normalized_result | {kind, view, coverage, item}'" "jq -c '{source: {kind: \"inline\", evidence: .}, view: {kind: \"summary\"}}' notes/js-full.ev.json > notes/js-view.json" "wc -c < notes/js-full.ev.json; rea inspect-analysis-view notes/js-view.json --format json | wc -c"
want t11 && step t11-sqlite "ls -la sqlite/" "rea inspect-sqlite-database sqlite/notes.db --format json | jq -c '.provider, .normalized_result.artifact, (.normalized_result.schema | {scope, completeness}, (.tables[] | {name, column_count, columns_completeness}), {indexes: [.indexes[].name], views: [.views[].name], triggers: [.triggers[].name]})'"
want t12 && step t12-sqlite-rows "rea inspect-sqlite-database sqlite/notes.db --table notes --column title --column big --column blob_val --row-limit 2 --format json | jq -c '.normalized_result.rows | (.values[]), {row_limit, returned_rows, truncated, order}'" "rea inspect-sqlite-database sqlite/notes.db --table pinned_notes --format json | jq -c '{code, details}'"
want t13 && step t13-pcap "rea inspect-pcap-capture pcap/lab65.pcap --format json | jq -c '.confidence, (.normalized_result | {packet_count, file_type, capture_duration_seconds}), .normalized_result.endpoints, .normalized_result.dns_queries, .normalized_result.tls_sni_values, .normalized_result.http_request_uris, [.normalized_result.protocol_distribution[] | \"\\(.packet_count) \\(.protocol)\"]'"
want t14 && step t14-packets "rea inspect-packet-capture pcap/lab65.pcap --fields ip.dst --fields tcp.dstport --fields tls.handshake.extensions_server_name --display_filter tcp --match_limit 3 --match_offset 6 --format json | jq -c '.normalized_result | .packets[], .output_window'" "rea inspect-packet-capture pcap/lab65.pcap --fields udp.port --fields data.data --display_filter 'udp.port==5555' --format json | jq -c '.normalized_result.packets[]'"
want t15 && step t15-wasm "rea inspect-wasm-artifact \$PWD/wasm/calc-v1.wasm --glue_paths \$PWD/wasm/glue.js --format json > notes/wasm-v1.json; jq -c '.confidence, (.normalized_result | {validation, runtime_execution, network_fetch}), .normalized_result.imports, .normalized_result.exports, .normalized_result.glue[0].references[0]' notes/wasm-v1.json"
want t16 && step t16-wasm-compare "rea inspect-wasm-artifact \$PWD/wasm/calc-v2.wasm --format json > notes/wasm-v2.json" "jq -n --slurpfile l notes/wasm-v1.json --slurpfile r notes/wasm-v2.json '{left: \$l[0], right: \$r[0], scope: \"both\"}' > notes/wasm-compare-input.json" "rea compare-wasm-interfaces notes/wasm-compare-input.json --format json | jq -c '.normalized_result | (.changes[] | \"\\(.direction) \\(.module // \"-\").\\(.name): \\(.state)\"), .summary'"
want t17 && step t17-go "rea inspect-go-binary go/hellogo --format json | jq -c '.confidence, (.normalized_result | {format, architecture}), (.normalized_result.build_info | {go_version, main: .module.main.path}), (.normalized_result.build_info.module.dependencies[] | {path, version}), [.normalized_result.build_info.module.settings[] | \"\\(.key)=\\(.value)\"]'"
want t18 && step t18-rust "rea inspect-rust-binary rust/hellorust-auditable --format json | jq -c '.confidence, (.normalized_result.auditable_metadata | {section_name, file_offset, compressed_bytes, uncompressed_bytes}), .normalized_result.auditable_metadata.packages[], .normalized_result.auditable_metadata.dependency_edges'" "rea inspect-rust-binary rust/hellorust-plain --format json | jq -c '.normalized_result.auditable_metadata, (.normalized_result.limitations[] | select(test(\"dep-v0 section was found\")))'"
want t19 && step t19-fuses "cat electron/stock/version; echo" "rea inspect-electron-fuses electron/stock/electron --format json | jq -r '.normalized_result | \"sentinel@\\(.slices[0].sentinels[0].sentinel_offset)\", (.slices[0].sentinels[0].fuses[0:6][] | \"  \\(.index) \\(.name) = \\(.state)\"), (.runtime_implications[] | \"  => \\(.subject): \\(.outcome)\")'" "rea inspect-electron-fuses electron/hardened/electron --format json | jq -r '.normalized_result | (.slices[0].sentinels[0].fuses[0:6][] | \"  \\(.index) \\(.name) = \\(.state)\"), (.runtime_implications[] | \"  => \\(.subject): \\(.outcome)\")'"
want t30 && step t30-tool-installs "sha256sum ~/.local/android/jadx-headless-mcp-0.7.1-all.jar ~/.local/android/ApiDemos-debug.apk" "\$REA_ADB_PATH version | head -2; \$REA_APKTOOL_COMMAND --version; binwalk --version 2>&1 | head -1; unblob --version; sasquatch -version 2>&1 | head -1; dotnet --version"
want t31 && step t31-android "rea inspect-android-package \$PWD/android/ApiDemos-debug.apk --format json | jq -c '.confidence, (.normalized_result | {package_name, version_name, min_sdk, target_sdk, class_count, resource_count, signature_verification}), .normalized_result.permissions[0:6], (.normalized_result.engine | {name, version})'" "rea search-android-classes \$PWD/android/ApiDemos-debug.apk ApiDemos --format json | jq -c '.normalized_result | {total_classes, matches, coverage}'"
want t32 && step t32-android-method "rea inspect-android-method \$PWD/android/ApiDemos-debug.apk io.appium.android.apis.ApiDemos onCreate --format json | jq -r '.normalized_result | \"\\(.method.reported_signature)  [\\(.representation), body \\(.body_status)]\", .source.text'" "rea decode-android-resources \$PWD/android/ApiDemos-debug.apk --no-strings --format json | jq -c '.normalized_result | .client, .metadata, {decoded_file_count, coverage}'" "rea list-adb-devices --format json | jq -c '.normalized_result // {code, message}'"
want t33 && rm -rf /workspace/re/lab65/notes/fw-x
want t33 && step t33-firmware "ls -la firmware/lab65-fw.bin" "rea inspect-firmware-regions \$PWD/firmware/lab65-fw.bin --format json | jq -c '.provider, (.normalized_result.regions[] | {offset, reported_size, signature})'" "rea extract-firmware \$PWD/firmware/lab65-fw.bin \$PWD/notes/fw-x --format json | jq -c '.provider, (.normalized_result | {coverage, gaps: [.extraction_gaps[] | {kind, range}]})'" "cd notes/fw-x && find . -type f | sort && cat firmware.bin_extract/512-180736.squashfs_v4_le_extract/etc/device.conf"
want t34 && step t34-firmware-ghidra "rea search notes/fw-x/firmware.bin_extract/512-180736.squashfs_v4_le_extract/bin/hellod hello-rust --provider ghidra --format json | jq -c '.subject.format, .subject.architecture, (.normalized_result | if type==\"array\" then .[0:2] else (.matches // .)[0:2] end), .confidence'"
want t35 && step t35-dotnet "rea inspect-managed-artifact dotnet/target/PromoLab.dll --format json | jq -c '(.normalized_result.classification | {status, runtime_family, implementation, managed_architecture}), (.normalized_result.assembly | {name, version}), .normalized_result.metadata.table_row_counts'" "rea inspect-managed-members dotnet/target/PromoLab.dll --type PromoLab.PromoCode --format json | jq -c '(.normalized_result.methods[] | {name, sig: \"\\(.signature.return_type) (\\(.signature.parameter_types|join(\", \")))\", il_bytes: .body.il_size}), .normalized_result.user_strings.literals, (.normalized_result.call_edges[] | \"\\(.caller) -> \\(.target_declaring_type).\\(.target_name)\")'" "rea inspect-managed-native-boundaries dotnet/target/PromoLab.dll --format json | jq -c '.normalized_result.pinvoke_imports[] | {member_name, import_scope_name, import_name}'"
want t36 && step t36-doctor-all "rea doctor --json | jq -r '\"healthy: \\(.healthy)\", (.checks[] | \"  \\(if .ok then \"PASS\" else \"FAIL\" end)  \\(.classification)  \\(.name)\")'" "rea inspect-apktool-client --format json | jq -c '.normalized_result.client // .normalized_result'" "rea inspect-adb-client --format json | jq -c '.normalized_result | {version: (.client.version // .version)}'" "rea inspect-pcap-client --format json | jq -c '.normalized_result.client | {tshark_version, capinfos_version}'"
want t21 && step t21-stars "curl -s https://api.github.com/repos/morluto/rea | jq '{full_name, stargazers_count, forks_count, pushed_at}'" "TZ=America/New_York date"
want t09 && step t09-mcp-paged "node /workspace/rea-65/tools/mcp.mjs /workspace/rea-65/tools/mcp-steps-paged.json notes/mcp-paged.json" "jq -r '.[0].serverInfo, (.[1] | \"tools/list: \\(.count) tools; new ones: \\(.match|join(\", \"))\")' notes/mcp-paged.json" "jq -c '.[2:10][] | {call: .step, args: (.arguments.view // .arguments.detail), coverage: (.result.normalized_result.coverage | {examined, total, next_offset, exhausted})}' notes/mcp-paged.json" "jq -c '.[3].result.normalized_result.items[] | {kind, path}' notes/mcp-paged.json; jq -c '.[8].result.normalized_result.page.items' notes/mcp-paged.json"
want t20 && step t20-connector "grep -o '\"version\":\"6[^\"]*\"' /home/box/.cursor/projects/workspace/agent-tools/1fa1225f-a97b-4f2b-abff-f7fe288fdd1e.txt | sort -u   # Grok Bot rea connector: binary_session" "sed -n 3p notes/connector-sqlite.txt | jq -c '{evidence_id, operation, tables: [.normalized_result.schema.tables[].name]}'   # connector call inspect_sqlite_database" "rea inspect-sqlite-database sqlite/notes.db --format json | jq -r .evidence_id   # same file through the CLI"
want t22 && step t22-snags "env -u REA_TSHARK_COMMAND rea inspect-packet-capture pcap/lab65.pcap --fields ip.src --format json | jq -c '{code, message}'" "PATH=/usr/bin:\$PATH node --version; PATH=/usr/bin:\$PATH node ~/.local/bin/rea inspect-sqlite-database sqlite/notes.db --format json | jq -c '{code, message}'" "jq -n --slurpfile l notes/wasm-v1.json --slurpfile r notes/wasm-v2.json '{left: {kind: \"inline\", evidence: \$l[0]}, right: {kind: \"inline\", evidence: \$r[0]}, scope: \"both\"}' > /tmp/bad-compare.json; rea compare-wasm-interfaces /tmp/bad-compare.json --format json | jq -c '{code, first_issues: [.details.issues[0:2][] | {path, reason}]}'" "jq -c '.normalized_result.extraction_gaps[0] | {kind, handler, dependencies}' notes/fw-extract.json   # first extract-firmware run, before installing sasquatch"
